insert into public.governorates (slug, name_ar, name_en, note_ar, discussion_order, sources) values ('south-sinai', 'محافظة جنوب سيناء', 'South Sinai', 'مواقع الغوص والمحميات والجبال تُسجل بأنواع منفصلة عن المتاحف ومعالم المدينة. تتغير هيئة الجزيرة البيضاء وإمكانية ظهورها مع المد والجزر.', 2, '[{"label_ar":"الشواطئ والغوص بشرم الشيخ","url":"https://www.experienceegypt.eg/en/Attraction-Details/186/beaches-snorkeling-diving"},{"label_ar":"المحميات","url":"https://www.experienceegypt.eg/en/attraction-details/185/national-parks-protected-areas"},{"label_ar":"دهب","url":"https://www.experienceegypt.eg/en/city/33/dahab"},{"label_ar":"طابا","url":"https://www.experienceegypt.eg/en/City/13/taba"},{"label_ar":"بوابة جنوب سيناء السياحية","url":"https://www.southsinai.gov.eg/Tourist"}]'::jsonb)
