insert into public.governorates (slug, name_ar, name_en, note_ar, discussion_order, sources) values ('giza', 'محافظة الجيزة', 'Giza', 'الواحات البحرية تابعة للجيزة. انطلاق الرحلة منها إلى الصحراء البيضاء لا يجعل الصحراء البيضاء جزءًا من الجيزة. كما أن متحف المومياوات وموقع اكتشافها ليسا مكانًا واحدًا تلقائيًا.', 4, '[{"label_ar":"الجيزة وعجائبها القديمة","url":"https://www.experienceegypt.eg/en/attraction-details/290/giza-ancient-wonders"},{"label_ar":"سقارة","url":"https://egymonuments.gov.eg/archaeological-sites/saqqara/"},{"label_ar":"دهشور","url":"https://egymonuments.gov.eg/archaeological-sites/dahshur/"},{"label_ar":"المتاحف","url":"https://www.experienceegypt.eg/en/attraction/16/museums"},{"label_ar":"الواحات البحرية","url":"https://www.experienceegypt.eg/en/city/25/al-bahariyya"},{"label_ar":"آثار الواحات البحرية","url":"https://www.experienceegypt.eg/en/Attraction-Details/221/archeological-sites-of-al-bahariyya"}]'::jsonb)
