insert into public.governorates (slug, name_ar, name_en, note_ar, discussion_order, sources) values ('aswan', 'محافظة أسوان', 'Aswan', 'إدفو وكوم أمبو تابعان لمحافظة أسوان. قصر إبريم يُشاهد عادةً من الرحلات البحرية، ولا يُعامل تلقائيًا كموقع متاح للنزول والزيارة. المقصود بفيلة موقع المعابد الحالي في أجيليكا.', 6, '[{"label_ar":"أسوان وأبو سمبل","url":"https://www.experienceegypt.eg/en/city/9/aswan-abu-simbel"},{"label_ar":"أسوان القديمة","url":"https://www.experienceegypt.eg/en/attraction-details/210/ancient-aswan"},{"label_ar":"معالم المدينة","url":"https://www.experienceegypt.eg/en/Attraction-Details/211/the-city"},{"label_ar":"أبو سمبل ومعابد النوبة","url":"https://www.experienceegypt.eg/en/attraction-details/208/abu-simbel-the-nubian-temples-downstream"}]'::jsonb)
