insert into public.governorates (slug, name_ar, name_en, note_ar, discussion_order, sources) values ('matrouh', 'محافظة مطروح', 'Matrouh', 'الساحل الشمالي منطقة ممتدة وليس محافظة مستقلة؛ لا يُنسب كله لمطروح. سيدي عبد الرحمن والضبعة ورأس الحكمة وجهات وليست معالم مفردة. كثير من شواطئ المنتجعات لها شروط دخول خاصة.', 8, '[{"label_ar":"العلمين","url":"https://www.experienceegypt.eg/en/attraction-details/251/al-alamein"},{"label_ar":"متحف العلمين العسكري","url":"https://www.mod.gov.eg/modwebsite/MuseumDetails.aspx?id=3"},{"label_ar":"وجهات وشواطئ الساحل","url":"https://www.experienceegypt.eg/en/Attraction-Details/253/egypt-s-exclusive-beaches-beach-activities"},{"label_ar":"مطروح","url":"https://www.experienceegypt.eg/en/attraction-details/294/city-breaks"},{"label_ar":"سيوة","url":"https://www.experienceegypt.eg/en/City/15/siwa-oasis"},{"label_ar":"شالي","url":"https://egymonuments.gov.eg/archaeological-sites/shali-village-in-siwa-oasis/"},{"label_ar":"آثار وتراث سيوة","url":"https://egymonuments.gov.eg/news/inaugurates-shali-fortress-and-the-aghurmi-mosque-in-the-siwa-oasis/"}]'::jsonb)
